  "PRODUCT_NAME",
  "PRODUCT_BUNDLE_IDENTIFIER",
  "PRODUCT_TYPE",
  "WRAPPER_EXTENSION",
  "SDKROOT",
  "PLATFORM_NAME",
  "SUPPORTED_PLATFORMS",
  "MACOSX_DEPLOYMENT_TARGET",
  "IPHONEOS_DEPLOYMENT_TARGET",
