// src/server.ts
var SERVER_NAME = "notarize";
var SERVER_VERSION = package_default.version;
var SERVER_INSTRUCTIONS = `Apple code signing, notarization, certificates, provisioning, entitlements, Gatekeeper/sandbox/TCC debugging, TestFlight and App Store Connect.

Start with: doctor (machine readiness) \u2192 detect_project (what the app is) \u2192 distribution_checklist (what is missing for the chosen target). Each result lists next_steps naming the tool to call.

Mutating tools (signing, keychain, notarization submits, uploads, App Store Connect changes) use plan + confirm: the first call returns a PREVIEW and a confirm_token and changes nothing. Show the preview to the user; only after they approve, call again with identical arguments plus confirm_token. Never invent tokens.

Read notarize://guides/* resources (or the apple-distribution skill) for background on any topic.`;
function createServer(ctx, tools = allTools) {
  const server = new McpServer(
    { name: SERVER_NAME, version: SERVER_VERSION },
    { instructions: SERVER_INSTRUCTIONS, capabilities: { logging: {} } }
  );
  for (const def of tools) {
    const shape = def.mutating ? { ...def.input, [CONFIRM_TOKEN_ARG]: confirmTokenSchema } : def.input;
    server.registerTool(
      def.name,
      {
        title: def.title,
        description: def.description,
        inputSchema: shape,
        annotations: {
          title: def.title,
          readOnlyHint: !def.mutating,
          openWorldHint: false,
          ...def.annotations
        }
      },
      async (args, extra) => {
        const toolExtra = {
          toolName: def.name,
          signal: extra?.signal,
          async progress(message2, progress, total) {
            const token = extra?._meta?.progressToken;
            if (token === void 0) return;
            await extra.sendNotification({
              method: "notifications/progress",
              params: { progressToken: token, progress: progress ?? 0, total, message: message2 }
            }).catch(() => {
            });
          }
        };
        try {
          return toCallToolResult(await def.handler(args ?? {}, ctx, toolExtra));
        } catch (e) {
          return toCallToolResult(errorOutput(e));
        }
      }
    );
  }
  registerResources(server);
  registerPrompts(server);
  return server;
}

// src/index.ts
var HELP = [
  `${SERVER_NAME} ${SERVER_VERSION} \u2014 stdio MCP server for Apple signing, notarization and App Store Connect.`,
  "",
  "Usage:",
  "  notarize-mcp                              speak MCP over stdio (what MCP clients run)",
  "  notarize-mcp --list-tools",
  "  notarize-mcp watch-job <job-id> [--state-dir DIR] [--interval SECONDS] [--max-minutes N]",
  "      Follow a background job (notarization, signing, upload\u2026). One line per status change;",
  "      exits 0 succeeded, 1 failed, 3 lost (server stopped), 4 max time reached. Built for Claude Code's Monitor tool.",
  "  notarize-mcp watch-notarization <submission-id> [--keychain-profile NAME] [--profile NAME] [--interval SECONDS] [--max-minutes N]",
  "      Poll Apple's notary service directly (works even if the MCP server restarted).",
  "      exits 0 Accepted, 1 Invalid/Rejected (prints top issues), 2 error, 4 max time reached.",
  "",
  "Environment:",
  "  ASC_KEY_ID, ASC_ISSUER_ID, ASC_PRIVATE_KEY_PATH | ASC_PRIVATE_KEY   App Store Connect API key",
  "  ASC_PROFILE                 credential profile name (see asc_auth configure)",
  "  NOTARY_KEYCHAIN_PROFILE     notarytool keychain profile",
  "  NOTARIZE_MCP_CONFIG_DIR     config dir (default ~/.config/notarize-mcp)",
  "  NOTARIZE_MCP_LOG_DIR        command transcript dir (default ~/Library/Logs/notarize-mcp)",
  "  NOTARIZE_MCP_STATE_DIR      background job state dir (default <log dir>/jobs)",
  "  NOTARIZE_MCP_AUTO_CONFIRM=1 skip preview/confirm (CI only)",
  ""
].join("\n");
async function main() {
  const argv = process.argv.slice(2);
  const [command, ...rest] = argv;
  if (command === "watch-job") {
    const { positional, flags } = parseFlags(rest);
    const id = requireArg(positional[0], "notarize-mcp watch-job <job-id>");
    return watchJob(id, {
      stateDir: flags["state-dir"],
      intervalMs: flags.interval ? Number(flags.interval) * 1e3 : void 0,
      maxMs: flags["max-minutes"] ? Number(flags["max-minutes"]) * 6e4 : void 0
    });
  }
  if (command === "watch-notarization") {
    const { positional, flags } = parseFlags(rest);
    const id = requireArg(positional[0], "notarize-mcp watch-notarization <submission-id>");
    return watchNotarization(createContext(), id, {
      keychainProfile: flags["keychain-profile"],
      profile: flags.profile,
      intervalMs: flags.interval ? Number(flags.interval) * 1e3 : void 0,
      maxMs: flags["max-minutes"] ? Number(flags["max-minutes"]) * 6e4 : void 0
    });
  }
  if (argv.includes("--version") || argv.includes("-v")) {
    process.stdout.write(`${SERVER_VERSION}
`);
    return 0;
  }
  if (argv.includes("--help") || argv.includes("-h")) {
    process.stdout.write(HELP);
    return 0;
  }
  if (argv.includes("--list-tools")) {
    for (const t of allTools)
      process.stdout.write(`${t.name}${t.mutating ? " (mutating)" : ""} \u2014 ${t.title}
`);
    return 0;
  }
  if (command) {
    process.stderr.write(`Unknown command: ${command}

${HELP}`);
    return 2;
  }
  const ctx = createContext();
  const server = createServer(ctx);
  const transport = new StdioServerTransport();
  await server.connect(transport);
  process.stderr.write(`${SERVER_NAME} MCP server ${SERVER_VERSION} running on stdio (${ctx.platform.os})
`);
  return void 0;
}
main().then(
  (code) => {
    if (code !== void 0) process.exit(code);
  },
  (err) => {
    process.stderr.write(`${SERVER_NAME}: ${err instanceof Error ? err.message : String(err)}
`);
    process.exit(2);
  }
);
